"use client";

import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { PlusIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { formatCount, ROLL_WHOLE } from "./lib/format";
import { BudgetBar } from "./mcp-servers/budget-bar";
import { SERVERS, TOKEN_BUDGET } from "./mcp-servers/data";
import { ServerRow } from "./mcp-servers/server-row";
import type { RowState } from "./mcp-servers/server-state";

const toolKey = (serverId: string, toolId: string) => `${serverId}/${toolId}`;

const START_ON = Object.fromEntries(SERVERS.flatMap((server) => server.tools.map((tool) => [toolKey(server.id, tool.id), tool.on])));
const START_STATE = Object.fromEntries(SERVERS.map((server): [string, RowState] => [server.id, server.state]));

/**
 * Manages the servers that lend an agent its tools. The header counts the
 * tools in use and what their descriptions cost in context against a budget,
 * with one bar segment per server. Each row opens to switch single tools on
 * or off; a server that needs sign in or failed offers that action instead.
 */
export function McpServers({ className }: { className?: string }) {
  const titleId = useId();
  const [toolsOn, setToolsOn] = useState(START_ON);
  const [states, setStates] = useState(START_STATE);
  const [openId, setOpenId] = useState<string | null>("diary");
  const [highlight, setHighlight] = useState<string | null>(null);
  const [message, setMessage] = useState("");
  const rowButtons = useRef(new Map<string, HTMLButtonElement>());
  const timers = useRef<number[]>([]);

  useEffect(() => {
    const pending = timers.current;
    return () => pending.forEach((id) => window.clearTimeout(id));
  }, []);

  const connected = SERVERS.filter((server) => states[server.id] === "connected");
  const segments = connected.map((server) => ({
    id: server.id,
    name: server.name,
    fill: server.fill,
    tokens: server.tools.reduce((sum, tool) => sum + (toolsOn[toolKey(server.id, tool.id)] ? tool.tokens : 0), 0),
  }));
  const toolCount = connected.reduce((sum, server) => sum + server.tools.filter((tool) => toolsOn[toolKey(server.id, tool.id)]).length, 0);
  const tokens = segments.reduce((sum, segment) => sum + segment.tokens, 0);
  const over = tokens - TOKEN_BUDGET;

  const toggle = (serverId: string, toolId: string, on: boolean) => {
    const next = { ...toolsOn, [toolKey(serverId, toolId)]: on };
    setToolsOn(next);
    const server = SERVERS.find((item) => item.id === serverId);
    const tool = server?.tools.find((item) => item.id === toolId);
    const total = connected.reduce(
      (sum, item) => sum + item.tools.reduce((inner, t) => inner + (next[toolKey(item.id, t.id)] ? t.tokens : 0), 0),
      0,
    );
    setMessage(`${tool?.name ?? "Tool"} ${on ? "on" : "off"}. ${formatCount(total)} of ${formatCount(TOKEN_BUDGET)} tokens in use.`);
  };

  const connect = (serverId: string) => {
    const server = SERVERS.find((item) => item.id === serverId);
    setStates((current) => ({ ...current, [serverId]: "connecting" }));
    setMessage(`Connecting to ${server?.name}.`);
    timers.current.push(
      window.setTimeout(() => {
        setStates((current) => ({ ...current, [serverId]: "connected" }));
        setMessage(`${server?.name} connected. Its tools now count toward the budget.`);
      }, 1400),
    );
  };

  const onRowKey = (event: KeyboardEvent<HTMLButtonElement>) => {
    const ids = SERVERS.map((server) => server.id);
    const current = ids.findIndex((id) => rowButtons.current.get(id) === event.currentTarget);
    let next: number | null = null;
    if (event.key === "ArrowDown") next = Math.min(ids.length - 1, current + 1);
    else if (event.key === "ArrowUp") next = Math.max(0, current - 1);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = ids.length - 1;
    if (next === null) return;
    event.preventDefault();
    rowButtons.current.get(ids[next] ?? "")?.focus();
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-col gap-4 border-b border-border px-5 py-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="min-w-0">
            <h2 id={titleId} className="text-base font-semibold">
              Tool servers
            </h2>
            <p className="text-sm text-muted-foreground">What the front desk agent can reach</p>
          </div>
          <Button variant="outline" size="sm">
            <PlusIcon aria-hidden="true" />
            Add server
          </Button>
        </div>
        <div className="flex flex-col gap-2">
          <p className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1 text-sm">
            <span>
              <span className="font-semibold tabular-nums">
                <NumberTicker value={toolCount} format={ROLL_WHOLE} />
              </span>{" "}
              tools in use,{" "}
              <span className="font-semibold tabular-nums">
                <NumberTicker value={tokens} format={ROLL_WHOLE} />
              </span>{" "}
              tokens of context
            </span>
            <span className={cn("text-xs tabular-nums", over > 0 ? STATUS_TEXT.bad : "text-muted-foreground")}>
              {over > 0 ? `${formatCount(over)} over the ${formatCount(TOKEN_BUDGET)} budget` : `${formatCount(TOKEN_BUDGET - tokens)} left of ${formatCount(TOKEN_BUDGET)}`}
            </span>
          </p>
          <BudgetBar segments={segments} budget={TOKEN_BUDGET} highlight={highlight} onHighlight={setHighlight} />
        </div>
      </header>

      <ul aria-label="Servers" className="flex flex-col py-2">
        {SERVERS.map((server) => (
          <ServerRow
            key={server.id}
            server={server}
            state={states[server.id] ?? server.state}
            isOn={(toolId) => Boolean(toolsOn[toolKey(server.id, toolId)])}
            onToggle={(toolId, on) => toggle(server.id, toolId, on)}
            open={openId === server.id}
            onOpenChange={(open) => setOpenId(open ? server.id : null)}
            onConnect={() => connect(server.id)}
            highlighted={highlight === server.id}
            onHighlight={(on) => setHighlight((current) => (on ? server.id : current === server.id ? null : current))}
            onRowKey={onRowKey}
            buttonRef={(node) => {
              if (node) rowButtons.current.set(server.id, node);
              else rowButtons.current.delete(server.id);
            }}
          />
        ))}
      </ul>
      <p role="status" className="sr-only">
        {message}
      </p>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

