import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const CENTS = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** Seconds as a short clock reading, such as "48s" or "2m 05s". */
export function formatSeconds(seconds: number) {
  const whole = Math.max(0, Math.round(seconds));
  if (whole < 60) return `${whole}s`;
  const minutes = Math.floor(whole / 60);
  const rest = whole % 60;
  if (minutes < 60) return `${minutes}m ${String(rest).padStart(2, "0")}s`;
  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, "0")}m`;
}

/** A token count, such as "840" or "12.4K". */
export const formatTokens = (value: number) => (value < 1000 ? WHOLE.format(Math.round(value)) : COMPACT.format(value));

/** A cost with cents, such as "$0.42". */
export const formatCost = (value: number) => CENTS.format(value);

/** A whole number with separators. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** Roll formats for `NumberTicker`. Module constants, because the ticker memoises its formatter on them. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
/** One decimal place, for a score or a percent. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };
/** Dollars with cents. */
export const ROLL_CENTS: Intl.NumberFormatOptions = { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 };

"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";

import { cn } from "@/lib/utils";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** One server's share of the context budget. */
export interface BudgetSegment {
  id: string;
  name: string;
  tokens: number;
  /** The class that colours the segment, such as `bg-chart-1`. */
  fill: string;
}

/** Props for the context budget bar. */
export interface BudgetBarProps {
  segments: BudgetSegment[];
  budget: number;
  /** The server in focus. Its segment keeps full colour and the others fade. */
  highlight: string | null;
  onHighlight: (id: string | null) => void;
}

// Critically damped: 2 * sqrt(420) is about 41, so a resized segment lands without a wobble.
const RESIZE: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };

/**
 * One bar for the whole context budget, split into a segment per connected
 * server. A segment resizes on a spring when a tool turns on or off. When the
 * tools pass the budget the bar scales to the total and a line marks the budget.
 * Decorative: the figures above it say the same in words.
 */
export function BudgetBar({ segments, budget, highlight, onHighlight }: BudgetBarProps) {
  const reduceMotion = useReducedMotion();
  const total = segments.reduce((sum, segment) => sum + segment.tokens, 0);
  const scale = Math.max(total, budget);
  return (
    <div aria-hidden="true" className="relative">
      <div className="flex h-3 w-full gap-0.5 overflow-hidden rounded-full bg-muted">
        {segments.map((segment) => (
          <motion.span
            key={segment.id}
            initial={false}
            animate={{ width: `${(segment.tokens / scale) * 100}%` }}
            transition={reduceMotion ? { duration: 0 } : RESIZE}
            onPointerEnter={() => onHighlight(segment.id)}
            onPointerLeave={() => onHighlight(null)}
            className={cn(
              "h-full shrink-0 first:rounded-l-full motion-safe:transition-opacity motion-safe:duration-150",
              segment.fill,
              highlight === null || highlight === segment.id ? "opacity-100" : "opacity-25",
            )}
          />
        ))}
      </div>
      {total > budget ? (
        <span
          className="absolute -inset-y-1 left-(--x) w-0.5 rounded-full bg-foreground"
          style={
            // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
            { "--x": `${(budget / scale) * 100}%` } as VarStyle
          }
        />
      ) : null}
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

