"use client";

import { type KeyboardEvent, type Ref, useId } from "react";

import { ChevronDownIcon, RefreshIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { PlugIcon } from "../icons";
import { formatTokens, ROLL_WHOLE } from "../lib/format";
import { AppMark } from "../parts/app-mark";
import { Reveal } from "../parts/reveal";
import type { ToolServer } from "./data";
import { type RowState, ServerStateMark } from "./server-state";

/** Props for one server row. */
export interface ServerRowProps {
  server: ToolServer;
  state: RowState;
  /** Whether each tool is on, by tool id. */
  isOn: (toolId: string) => boolean;
  onToggle: (toolId: string, on: boolean) => void;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Signs in or retries, depending on the state. */
  onConnect: () => void;
  highlighted: boolean;
  onHighlight: (on: boolean) => void;
  /** Moves focus between the rows' disclosure buttons. */
  onRowKey: (event: KeyboardEvent<HTMLButtonElement>) => void;
  buttonRef: Ref<HTMLButtonElement>;
}

/**
 * One server: its mark, name and state, how many of its tools are on and what
 * they cost, or a sign-in or retry button. The row opens to list each tool with a switch.
 */
export function ServerRow({ server, state, isOn, onToggle, open, onOpenChange, onConnect, highlighted, onHighlight, onRowKey, buttonRef }: ServerRowProps) {
  const panelId = useId();
  const live = state === "connected";
  const onTools = server.tools.filter((tool) => isOn(tool.id));
  const tokens = onTools.reduce((sum, tool) => sum + tool.tokens, 0);

  return (
    <li
      className="relative"
      onPointerEnter={() => onHighlight(true)}
      onPointerLeave={() => onHighlight(false)}
      onFocus={() => onHighlight(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) onHighlight(false);
      }}
    >
      {/* A bar in the server's colour marks the row whose segment is in focus, with no fill to stack on a see-through card. */}
      <span
        aria-hidden="true"
        className={cn("absolute inset-y-3 left-1.5 w-1 rounded-full motion-safe:transition-opacity", server.fill, highlighted ? "opacity-100" : "opacity-0")}
      />
      <div className="relative flex items-center gap-2 px-3 py-1">
        <Button
          ref={buttonRef}
          variant="ghost"
          aria-expanded={open}
          aria-controls={panelId}
          data-server-row=""
          onClick={() => onOpenChange(!open)}
          onKeyDown={onRowKey}
          size="sm"
          className="min-w-0 flex-1 justify-start"
        >
<span className="flex min-h-12 w-full min-w-0 items-center gap-3 px-2 py-2 text-left font-normal">
          <AppMark app={server.app} size="md" />
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-sm font-medium">{server.name}</span>
            <span className="flex min-w-0 items-center gap-2">
              <ServerStateMark state={state} />
              <span className="hidden truncate text-xs text-muted-foreground @sm:inline">{server.host}</span>
            </span>
          </span>
          {live ? (
            <span className="flex shrink-0 flex-col items-end text-xs text-muted-foreground tabular-nums @md:flex-row @md:gap-4">
              <span>
                {onTools.length} of {server.tools.length} tools
              </span>
              <span className="font-medium text-foreground">
                <NumberTicker value={tokens} format={ROLL_WHOLE} /> tokens
              </span>
            </span>
          ) : null}
          <ChevronDownIcon
            aria-hidden="true"
            className={cn("size-4 shrink-0 text-muted-foreground motion-safe:transition-transform", open && "rotate-180")}
          />
        </span>
</Button>
        {state === "sign-in" ? (
          <Button variant="outline" size="sm" onClick={onConnect}>
            <PlugIcon aria-hidden="true" />
            Sign in
          </Button>
        ) : null}
        {state === "error" ? (
          <Button variant="outline" size="sm" onClick={onConnect}>
            <RefreshIcon aria-hidden="true" />
            Retry
          </Button>
        ) : null}
      </div>
      <Reveal open={open} id={panelId}>
        <ul aria-label={`${server.name} tools`} className="relative flex flex-col gap-1 px-5 pt-1 pb-3 @md:pl-16">
          {live ? null : (
            <li className="pb-1 text-xs text-muted-foreground">
              {state === "error" ? "Retry the connection to use these tools." : "Sign in to use these tools."}
            </li>
          )}
          {server.tools.map((tool) => (
            <li key={tool.id} className="flex items-center gap-3 rounded-lg py-1.5">
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="text-sm">{tool.name}</span>
                <span className="text-xs text-muted-foreground">{tool.summary}</span>
              </span>
              <span className="shrink-0 text-xs text-muted-foreground tabular-nums">{formatTokens(tool.tokens)}</span>
              <Switch
                aria-label={`${tool.name}, ${formatTokens(tool.tokens)} tokens`}
                checked={isOn(tool.id)}
                disabled={!live}
                onCheckedChange={(on) => onToggle(tool.id, on)}
              />
            </li>
          ))}
        </ul>
      </Reveal>
    </li>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

/** Props for a region that opens to its full height. */
export interface RevealProps {
  open: boolean;
  children: ReactNode;
  /** An id, so the control that opens it can point at it with `aria-controls`. */
  id?: string;
  className?: string;
}

// Critically damped: 2 * sqrt(380) is about 39, so the height lands without a wobble.
const HEIGHT: Transition = { type: "spring", stiffness: 380, damping: 39, mass: 1 };

/**
 * Opens from zero to its full height on a critically damped spring. The
 * content fades in a beat after the height starts and fades out a beat before
 * it ends, and rises a little into place. With reduced motion it appears at once.
 */
export function Reveal({ open, children, id, className }: RevealProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence initial={false}>
      {open ? (
        <motion.div
          key="reveal"
          id={id}
          initial={reduceMotion ? false : { height: 0 }}
          animate={{ height: "auto", transition: reduceMotion ? { duration: 0 } : HEIGHT }}
          exit={reduceMotion ? { height: 0, transition: { duration: 0 } } : { height: 0, transition: { ...HEIGHT, delay: 0.05 } }}
          className="overflow-hidden"
        >
          <motion.div
            initial={reduceMotion ? false : { opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0, transition: { duration: 0.18, delay: reduceMotion ? 0 : 0.06 } }}
            exit={{ opacity: 0, y: reduceMotion ? 0 : 4, transition: { duration: reduceMotion ? 0 : 0.12 } }}
            className={cn(className)}
          >
            {children}
          </motion.div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

"use client";

import { AlertTriangleIcon, CircleCheckIcon, CircleXIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";
import { LoaderIcon } from "../icons";

/** Every state a server row can show, including the short wait while it connects. */
export type RowState = "connected" | "sign-in" | "error" | "connecting";

const LOOK = {
  connected: { Icon: CircleCheckIcon, word: "Connected", tone: STATUS_TEXT.good },
  "sign-in": { Icon: AlertTriangleIcon, word: "Needs sign in", tone: STATUS_TEXT.watch },
  error: { Icon: CircleXIcon, word: "Could not connect", tone: STATUS_TEXT.bad },
  connecting: { Icon: LoaderIcon, word: "Connecting", tone: "text-muted-foreground" },
} satisfies Record<RowState, { Icon: typeof CircleCheckIcon; word: string; tone: string }>;

/** A server's state as an icon and a word, so colour never carries it alone. */
export function ServerStateMark({ state, className }: { state: RowState; className?: string }) {
  const { Icon, word, tone } = LOOK[state];
  return (
    <span className={cn("inline-flex items-center gap-1 text-xs whitespace-nowrap", tone, className)}>
      <Icon aria-hidden="true" className={cn("size-3.5", state === "connecting" && "motion-safe:animate-spin")} />
      {word}
    </span>
  );
}
